from collections import Counter

def detect_line_color(grid):
    h,w=len(grid),len(grid[0])
    candidates=[]
    for col in sorted({x for row in grid for x in row}):
        rs=[i for i,row in enumerate(grid) if row.count(col) >= 0.5*w]
        cs=[j for j in range(w) if sum(row[j]==col for row in grid) >= 0.5*h]
        def uniform(seq):
            ds=[b-a for a,b in zip(seq,seq[1:])]
            return len(seq)>=3 and len(set(ds))==1
        if uniform(rs) and uniform(cs):
            candidates.append((len(rs)*len(cs),len(rs)+len(cs),col,rs,cs))
    if not candidates:
        raise ValueError('no line color')
    return max(candidates)

def solve_grid(grid):
    prod,total,line,rs,cs=detect_line_color(grid)
    lattice=[[grid[r][c] for c in cs] for r in rs]
    coords=[(i,j) for i,row in enumerate(lattice) for j,v in enumerate(row) if v!=line]
    r0=min(i for i,j in coords); r1=max(i for i,j in coords)
    c0=min(j for i,j in coords); c1=max(j for i,j in coords)
    mat=[row[c0:c1+1] for row in lattice[r0:r1+1]]
    bg=Counter(x for row in grid for x in row if x!=line).most_common(1)[0][0]
    out=[]
    for i in range(len(mat)-1):
        row=[]
        for j in range(len(mat[0])-1):
            vals=[mat[i][j],mat[i][j+1],mat[i+1][j],mat[i+1][j+1]]
            row.append(vals[0] if len(set(vals))==1 else bg)
        out.append(row)
    return out, (line,rs,cs,lattice,mat,bg)

